function renderRhythmInstrumentsHTML_AR(filterCat = "all") {
  const ensembleCard = `
    <div class="article-highlight-box" style="margin-bottom:0.2rem;">
      <h4>كيف تتقاسم الآلات الإيقاعية نمطاً واحداً (توزيع الترددات):</h4>
      <p style="font-size:0.78rem; color:var(--raccoon-dark); line-height:1.4;">
        ليبقى الإيقاع واضحاً، تشغل كل آلة نطاقها الصوتي الخاص: <strong>الكيك</strong> في الأسفل، <strong>السنير</strong> ينفجر في الوسط، و<strong>الهاي-هات والشيكر</strong> يتألقان في الأعلى.
      </p>
      <div class="k-btn-row" style="margin-top:0.35rem;">
        <button class="btn-tool" data-play-rhythm="band-groove">▶ إيقاع الفرقة الكامل (كيك + سنير + هاي-هات + شيكر)</button>
      </div>
    </div>
  `;

  const items = RHYTHM_INSTRUMENTS_DATA_AR.filter(item => filterCat === "all" || item.category === filterCat);
  return (filterCat === "all" ? ensembleCard : "") + items.map(item => `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag ${item.tagClass}">${item.tag}</span>
        <span class="k-ratio-chip">${item.role.split("(")[0].trim()}</span>
      </div>
      <h4>${item.name}</h4>
      <p><strong>الدور:</strong> ${item.role}</p>
      <p>${item.desc}</p>
      ${item.rhythmKey ? `
        <div class="k-btn-row">
          <button class="btn-tool" data-play-rhythm="${item.rhythmKey}">▶ ${item.btnLabel}</button>
        </div>
      ` : ""}
    </article>
  `).join("");
}

function renderVocalsReferenceHTML_AR() {
  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">الصوت البشري</span>
        <span class="k-ratio-chip">الآلة الأولى</span>
      </div>
      <h4>كيف يُنتج الصوت البشري النغمات؟</h4>
      <p>يجمع صوتك ثلاثة أنظمة صوتية وميكانيكية متكاملة داخل آلة حية واحدة. وعلى عكس الجيتار أو الفلوت، يتغيّر «صندوق الرنين» خلال أجزاء من الألف من الثانية ليشكّل الطبقة، والشدة، والتوافقيات، والحروف المتحركة والساكنة في آنٍ واحد.</p>

      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>1. مصدر الطاقة (التنفس ودعم الحجاب الحاجز)</strong>
          عند الشهيق يهبط <em>الحجاب الحاجز</em> بسلاسة ليوسّع سعة الرئتين. وأثناء الغناء، تنظّم عضلات البطن والأضلاع <em>ضغط هواء ثابتاً تحت المزمار</em> («دعم التنفس») دون أي شدٍّ في الحلق.
        </div>
        <div class="physics-fact-item">
          <strong>2. مصدر الاهتزاز (الحنجرة والأحبال الصوتية)</strong>
          تمتد داخل الحنجرة <em>طيتان صوتيتان (حبلان صوتيان)</em> مرنتان. يدفعهما تيار الهواء للانغلاق والانفتاح بانتظام عبر <em>تأثير برنولي</em> (من 100 إلى 1000 مرة في الثانية)، منتجاً صوتاً خاماً غنياً بالتوافقيات.
        </div>
        <div class="physics-fact-item">
          <strong>3. الرنّان (المجرى الصوتي والفورمانت)</strong>
          ترشّح تجاويف الحلق والفم والأنف هذا الصوت الخام. وتؤدي حركة اللسان والفك والشفتين والحنك الرخو إلى إزاحة قمم الرنين المسماة <em>الفورمانت (Formants)</em>، محوّلةً حرف «أو» الدافئ إلى «إي» اللامع.
        </div>
        <div class="physics-fact-item">
          <strong>4. فورمانت المغني (~3000 Hz)</strong>
          بتوسيع البلعوم السفلي، يركّز مغنو الأوبرا الطاقة الصوتية حول 2.8–3.2 kHz — تحديداً في الفجوة التي يتركها طيف الأوركسترا — مما يتيح لصوت واحد دون ميكروفون أن يعلو بوضوح فوق 80 آلة موسيقية!
        </div>
      </div>

      <div class="k-btn-row">
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="C4,E4,G4,C5" data-dur="1.9" data-step="0">▶ استمع لتآلف الكورال</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">المناطق الصوتية والتقنيات</span>
        <span class="k-ratio-chip">ألوان الصوت</span>
      </div>
      <h4>المناطق الصوتية (Registers) وتقنيات الغناء</h4>
      <p>تبعاً لعضلات الحنجرة النشطة وما إذا كانت الأحبال الصوتية تهتز بكامل سماكتها أم بحوافها الرقيقة فقط، يتبدل طابع الصوت جذرياً:</p>

      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>صوت الصدر (المنطقة الأساسية، M1)</strong>
          تهتز الكتلة العضلية الكاملة للأحبال الصوتية معاً. يُنتج طابعاً دافئاً وراسخاً وغنياً بالتوافقيات: وهو طبقة كلامنا الطبيعية وأساس القوة في المنطقتين الجهيرة والمتوسطة.
        </div>
        <div class="physics-fact-item">
          <strong>صوت الرأس والفالسيتو (M2)</strong>
          تستطيل الأحبال الصوتية وترقّ فتهتز حوافها الخارجية الدقيقة فحسب. يمنح لوناً خفيفاً شبيهاً بالفلوت ومحلّقاً (صوت رأس غنائي متجانس أو <em>فالسيتو</em> هوائي مميز).
        </div>
        <div class="physics-fact-item">
          <strong>الصوت المختلط (Mix Voice)</strong>
          يبني جسراً سلساً عبر منطقة الانتقال (<em>Passaggio</em>). ويحافظ التوازن العضلي الدقيق على اتصال اللون الصوتي من الجهير إلى الحاد دون انكسار مفاجئ.
        </div>
        <div class="physics-fact-item">
          <strong>البيلتينغ (البوب، المسرح الغنائي، الغوسبل)</strong>
          يحمل امتلاء صوت الصدر صعوداً إلى الطبقات الحادة عبر دعم تنفس قوي وتشكيل حروف علة مفتوحة: حضور جريء ومباشر حتى حدود G5/C6.
        </div>
        <div class="physics-fact-item">
          <strong>الفيبراتو (Vibrato)</strong>
          تموّج طبيعي مرن ومنتظم في الطبقة والشدة حول 5–7 Hz. يضفي دفئاً على النغمات الممتدة ويساعد الصوت المنفرد على البروز بوضوح فوق المجموعة.
        </div>
        <div class="physics-fact-item">
          <strong>السكات والغناء التوافقي (Overtone Singing)</strong>
          في الجاز، يحاكي <em>السكات (Scat)</em> عزف آلات النفخ المنفرد بمقاطع إيقاعية («شو-بي-دو»). أما في <em>الغناء التوافقي</em>، فيُبرز تشكيل اللسان الدقيق توافقيةً ضيقة فوق نغمة قرار ثابتة — فيُسمع صوتان في وقت واحد!
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">الكتابة الكورالية (SATB)</span>
        <span class="k-ratio-chip">الأصوات والمدى الصوتي</span>
      </div>
      <h4>في قلب الكورال: أقسام SATB والمدى الصوتي</h4>
      <p>تتبع الكورالات المختلطة حول العالم توزيع <strong>SATB</strong> — المسمى من الأعلى إلى الأسفل تبعاً للأقسام الأربعة الرئيسية. وغالباً ما تقسّم الكورالات السيمفونية الكبرى كل قسم إلى أول (I) وثانٍ (II) لتشكيل ثمانية أصوات: <em>SSAATTBB</em>.</p>

      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>السوبرانو (S) • المدى النموذجي C4–C6</strong>
          أعلى صوت نسائي أو طفولي. يحمل عادةً اللحن الرئيسي، والهارمونيات العليا، والإشراقة البلورية في التآلفات.
        </div>
        <div class="physics-fact-item">
          <strong>الألتو / الكونترالتو (A) • المدى النموذجي F3–E5</strong>
          الصوت النسائي الأعمق (أو صوت الكونترتينور). يمنح الدفء الداخلي للتآلف (الثالثات، السابعات، والتعليقات التعبيرية) أسفل اللحن مباشرة.
        </div>
        <div class="physics-fact-item">
          <strong>التينور (T) • المدى النموذجي C3–A4</strong>
          الصوت الرجالي الحاد (يُكتب غالباً في مفتاح صول ويُسمع أخفض بأوكتاف!). يربط النصفين العلوي والسفلي بألحان مضادة غنائية أو نغمات عالية مشرقة.
        </div>
        <div class="physics-fact-item">
          <strong>الباص (B) • المدى النموذجي E2–E4</strong>
          أعمق صوت رجالي والركيزة الصوتية للكورال. يثبّت الباص النغمة الأساسية للتآلف: وعندما يضبط الباص طبقته بدقة، يستقر التآلف بأكمله فوراً في مكانه.
        </div>
        <div class="physics-fact-item">
          <strong>الميتزو سوبرانو والباريتون والكونترتينور</strong>
          ثلاثة أصوات وسطية أساسية: <em>الميتزو سوبرانو</em> (A3–A5، جسر ثري بين السوبرانو والألتو)، و<em>الباريتون</em> (G2–G4، أكثر المدى الرجالي شيوعاً)، و<em>الكونترتينور</em> (رجل يغني في مدى الألتو بصوت رأس مدرَّب).
        </div>
        <div class="physics-fact-item">
          <strong>تشكيلات صوتية أخرى</strong>
          تحرص <em>كورالات النساء (SSAA)</em> و<em>كورالات الرجال (TTBB / الباربرشوب)</em> على تقارب التآلفات لإبراز الرنين التوافقي. أما فرق <em>الأكابيلا</em> الحديثة فتضيف الإيقاع الفموي (البيت بوكس) بديلاً لطقم الدرامز.
        </div>
      </div>

      <div class="k-btn-row">
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="G4,B4,D5,G5" data-dur="0.95" data-step="320">▶ مدى السوبرانو</button>
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="G3,Bb3,D4,F4" data-dur="0.95" data-step="320">▶ مدى الألتو</button>
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="C3,E3,G3,B3" data-dur="0.95" data-step="320">▶ مدى التينور</button>
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="E2,G2,B2,E3" data-dur="1.05" data-step="340">▶ أساس الباص</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">الضبط الصوتي والاستماع</span>
        <span class="k-ratio-chip">الضبط الطبيعي الصافي</span>
      </div>
      <h4>لماذا قد يبدو كورال الأكابيلا أصفى من البيانو؟</h4>
      <p>تُضبط آلات البيانو وفق نظام <strong>التعديل المتساوي ذي 12 نصف بُعد</strong>: فتكون الثالثات الكبيرة فيه أحدّ بنحو 14 سنتاً حتى تظل السلالم الاثنا عشر كلها صالحة للعزف. أما المغنون فليسوا مقيّدين بمفاتيح أو مطارق ثابتة.</p>
      <p>عند الغناء دون مرافقة آلية، يضبط المنشدون الماهرون مسافاتهم غريزياً وفق <strong>النسب الصافية للضبط الطبيعي</strong> (2:1 للأوكتاف، 3:2 للخامسة، 5:4 للثالثة الكبيرة). ولحظة تستقر الثالثة الكبيرة بلا أي تذبذب، تتعزز التوافقيات المشتركة ويتفتح التآلف بأكمله بإشراقة مدهشة (تأثير «رنين الباربرشوب» الشهير).</p>
      <div class="k-btn-row">
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="C3,G3,E4,C5" data-dur="1.4" data-step="460">▶ بناء صوتاً تلو الآخر (باص → سوبرانو)</button>
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="C3,G3,E4,C5" data-dur="2.4" data-step="0">▶ تآلف كورال SATB كامل</button>
        <button class="btn-tool" data-open-warmup="true">▶ افتح إحماء الصوت لـ 5 دقائق</button>
      </div>
    </article>
  `;
}

