function renderModesReferenceHTML_AR(familyFilter = "all") {
  const list = MODES_ENCYCLOPEDIA_AR.filter(m => familyFilter === "all" || m.family === familyFilter);

  const introHeader = `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">المبدأ الأساسي</span>
        <span class="k-ratio-chip">النسبي مقابل الموازي</span>
      </div>
      <h4>ما هو النمط (Mode) بالضبط؟</h4>
      <p>
        ينشأ <strong>النمط (Mode)</strong> عندما تستخدم مجموعة النغمات نفسها تماماً، ولكنك تختار نغمة مختلفة لتكون <strong>مركز الاستقرار (درجة القرار / التونيك)</strong>. ابقَ على المفاتيح البيضاء للبيانو فقط (نغمات C كبير)؛ كل نقطة بداية ترسم تسلسلاً جديداً من الأبعاد الكاملة والأنصاف: ابدأ من <code>D</code> فتحصل على <em>الدوري</em>، ومن <code>E</code> على <em>الفريجي</em>، ومن <code>F</code> على <em>الليدي</em>، ومن <code>G</code> على <em>الميكسوليدي</em>، ومن <code>A</code> على <em>الإيولي</em>، ومن <code>B</code> على <em>اللوكري</em>.
      </p>
      <div class="k-compare-grid">
        <div class="k-compare-box is-sage">
          <h5>1. المقاربة النسبية (المفاتيح نفسها)</h5>
          <p>عملية لمعرفة جغرافية لوحة المفاتيح: «D دوري يستخدم مفاتيح C كبير نفسها». لكنها قد تربك الأذن في البداية لأن C لا تزال تمارس جاذبيتها.</p>
        </div>
        <div class="k-compare-box is-peach">
          <h5>2. المقاربة الموازية (النغمة الأساسية نفسها!)</h5>
          <p><strong>مفتاح تدريب الأذن:</strong> اعزف الأنماط السبعة كلها بدءاً من <code>C</code>! عندها تكشف نغمة مميِّزة واحدة لون النمط فوراً (مثل <code>C → F♯</code> = ليدي، <code>C → Bb</code> = ميكسوليدي).</p>
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">طيف الإشراق النمطي</span>
        <span class="k-ratio-chip">مشرق ← داكن</span>
      </div>
      <h4>الترتيب من الأكثر إشراقاً إلى الأكثر قتامة (وفق دائرة الخامسات)</h4>
      <p>
        رتّب الأنماط السبعة من الأكثر إشراقاً إلى الأكثر قتامة بدلاً من الدرجات 1–7: في كل خطوة <strong>تنخفض نغمة واحدة فقط بمقدار نصف بُعد</strong>، تماماً وفق ترتيب دائرة الخامسات:
      </p>
      <div class="mode-spectrum-strip">
        <span class="mode-spec-chip is-bright">1. ليدي (#4)</span>
        <span class="mode-spec-chip">2. أيوني</span>
        <span class="mode-spec-chip">3. ميكسوليدي (b7)</span>
        <span class="mode-spec-chip">4. دوري (b3, b7)</span>
        <span class="mode-spec-chip">5. إيولي (+b6)</span>
        <span class="mode-spec-chip">6. فريجي (+b2)</span>
        <span class="mode-spec-chip is-dark">7. لوكري (+b5)</span>
      </div>
    </article>

    <div class="k-filter-row" aria-label="تصفية الأنماط">
      <button class="k-filter-pill ${familyFilter === "all" ? "active" : ""}" data-mfilter="all">الكل (9)</button>
      <button class="k-filter-pill ${familyFilter === "major" ? "active" : ""}" data-mfilter="major">عائلة الكبير (3)</button>
      <button class="k-filter-pill ${familyFilter === "minor" ? "active" : ""}" data-mfilter="minor">عائلة الصغير (4)</button>
      <button class="k-filter-pill ${familyFilter === "variant" ? "active" : ""}" data-mfilter="variant">تنويعات الصغير (2)</button>
    </div>
  `;

  const cards = list.map(m => `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag ${m.family === "major" ? "tag-peach" : m.family === "minor" ? "tag-lilac" : "tag-sage"}">${m.familyLabel} • ${m.brightness}</span>
        <span class="k-ratio-chip">${m.formula}</span>
      </div>
      <h4>${m.name} (مثال على ${m.rootLabel})</h4>
      <p class="k-char">${m.stammton}</p>
      <p><strong>النغمة المميِّزة:</strong> ${m.charNote}<br><strong>البنية:</strong> <code>${m.steps}</code></p>
      <p>${m.desc}</p>
      <p>${m.usage}</p>
      <div class="k-btn-row">
        <button class="btn-tool" data-play-mode-scale="${m.id}">▶ السلم (${m.rootLabel})</button>
        <button class="btn-tool" data-play-mode-vamp="${m.id}">▶ حلقة تآلفات: ${m.vamp}</button>
      </div>
    </article>
  `).join("");

  const tipsCard = `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">التأليف والهارموني النمطي</span>
        <span class="k-ratio-chip">الحفاظ على مركز النمط</span>
      </div>
      <h4>كيف تؤلف نمطياً دون الانزلاق إلى السلم الكبير؟</h4>
      <ul class="k-physics-list">
        <li><strong>تجنّب ترايتون السلم الأم:</strong> ضمن نغمات C كبير، يشكّل <code>F</code> و<code>B</code> ترايتون G7 الذي يجذب الأذن فوراً نحو C. هل تؤلف على D دوري أو G ميكسوليدي؟ تجنّب الإلحاح على G7 → C كي يحافظ نمطك على مركزه.</li>
        <li><strong>اعتمد على حلقات من تآلفين:</strong> بدلاً من القفلات الوظيفية الطويلة، دع القطعة تتنفس بين تآلف القرار والتآلف المجاور الذي يضم <strong>النغمة المميِّزة</strong> (مثل <code>Cm – F</code> في C دوري لإبراز <code>A</code> المشرقة).</li>
        <li><strong>ثبّت القطعة بنغمة قرار مستمرة (Pedal):</strong> إبقاء خامسة مفتوحة في الباص يرسّخ المركز النمطي فوراً، فتبرز كل مسافة مميِّزة فوقها بوضوح تام.</li>
      </ul>
    </article>
  `;

  return introHeader + `<div class="knowledge-list">${cards}</div>` + tipsCard;
}

