function renderKeysReferenceHTML_AR(circleFilter = "all") {
  const list = KEYS_CIRCLE_DATA_AR.filter(k => circleFilter === "all" || k.group === circleFilter);

  const theoryIntro = `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">1. المفهوم الأساسي</span>
        <span class="k-ratio-chip">المقامات ودليل المقام</span>
      </div>
      <h4>السلم مقابل المقام (Key): ماذا يفعل المقام فعلياً؟</h4>
      <p>
        <strong>السلم (Scale)</strong> هو مجرد قائمة مرتبة من النغمات (مثل C–D–E–F–G–A–B–C). أما <strong>المقام / الدرجة النغمية (Key)</strong> فيصف <em>نظام الجاذبية المغناطيسية</em> بأكمله حول مركز واحد: يحدد نقطة الاستقرار (<strong>درجة القرار / التونيك</strong>)، واللون (<strong>الكبير</strong> المشرق مقابل <strong>الصغير</strong> العميق)، وعلامات التحويل الثابتة (♯ أو ♭) عبر <strong>دليل المقام</strong>.
      </p>
      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>لماذا يوجد دليل المقام؟</strong>
          يتطلب كل سلم كبير نمط المسافات نفسه تماماً: <code>W – W – H – W – W – W – H</code> (أنصاف الأبعاد بين 3–4 و7–8). إذا بدأت من <code>G</code> بدلاً من C، ستكون الدرجة السابعة (<code>F</code>) أخفض مما ينبغي: لذا يجب رفعها إلى <code>F♯</code> لاستعادة النغمة الحساسة!
        </div>
        <div class="physics-fact-item">
          <strong>دليل المقام مقابل علامات التحويل العارضة</strong>
          يوضع <strong>دليل المقام</strong> بجانب المفتاح مباشرة ويسري على القطعة كلها. أما <strong>علامة التحويل العارضة</strong> وسط المازورة فتمنح لوناً مؤقتاً ينتهي عند خط المازورة.
        </div>
      </div>
    </article>

    <div class="k-sibling-bar">
      <span><strong>استكشف بالعين والأذن:</strong> افتح عجلة دائرة الخامسات التفاعلية مع التآلفات الحية والانتقالات المقامية.</span>
      <button type="button" class="btn-tool" data-jump-ref="circle-of-fifths">افتح دائرة الخامسات →</button>
    </div>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">2. منطق دائرة الخامسات</span>
        <span class="k-ratio-chip">3:2 ← 12 مقاماً</span>
      </div>
      <h4>لماذا تشكّل المقامات الاثنا عشر قرص ساعة مثالياً؟</h4>
      <p>
        مباشرة بعد الأوكتاف (2:1)، تُعد <strong>الخامسة التامة (3:2)</strong> أقوى رابط هارموني في الموسيقى. تحرك مع عقارب الساعة بخامسات صاعدة (<code>C → G → D → A → E → B → F♯</code>): تضيف كل خطوة علامة <strong>دييز (♯)</strong> جديدة. وتحرك عكس عقارب الساعة برابعات صاعدة (<code>C → F → Bb → Eb → Ab → Db → Gb</code>): تضيف كل خطوة علامة <strong>بيمول (♭)</strong> جديدة.
      </p>
      <div class="k-compare-grid">
        <div class="k-compare-box is-peach">
          <h5>مع عقارب الساعة: مقامات الدييز (♯)</h5>
          <p><strong>ترتيب المقامات:</strong> <em>G, D, A, E, B, F♯</em>.<br><strong>ترتيب الدييز:</strong> <code>F♯ – C♯ – G♯ – D♯ – A♯ – E♯</code> (آخر دييز هو دائماً النغمة الحساسة أسفل درجة القرار بنصف بُعد!).</p>
        </div>
        <div class="k-compare-box is-lilac">
          <h5>عكس عقارب الساعة: مقامات البيمول (♭)</h5>
          <p><strong>ترتيب المقامات:</strong> <em>F, Bb, Eb, Ab, Db, Gb</em>.<br><strong>ترتيب البيمول:</strong> <code>Bb – Eb – Ab – Db – Gb – Cb</code>. حيلة سريعة: <strong>البيمول قبل الأخير</strong> يمنحك اسم المقام الكبير!</p>
        </div>
      </div>
      <p class="k-tip"><strong>فاصلة فيثاغورس والترادف الإنهارموني:</strong> تكديس 12 خامسة صافية (3:2) يتجاوز 7 أوكتافات بنحو 23.5 سنتاً (<em>فاصلة فيثاغورس</em>). يوزّع <strong>التعديل المتساوي</strong> الحديث هذا الفارق الضئيل على 12 نصف بُعد، بحيث يلتقي <code>F♯ كبير</code> (6♯) و<code>Gb كبير</code> (6♭) على مفاتيح البيانو نفسها تماماً.</p>
    </article>

    <div class="section-heading-row">
      <h2 class="section-heading">3. الأطلس الكامل للمقامات الـ 12</h2>
    </div>

    <div class="k-filter-row" aria-label="تصفية المقامات حسب دليل المقام">
      <button class="k-filter-pill ${circleFilter === "all" ? "active" : ""}" data-kfilter="all">جميع المقامات الـ 12</button>
      <button class="k-filter-pill ${circleFilter === "neutral" ? "active" : ""}" data-kfilter="neutral">C / Am (0 علامات)</button>
      <button class="k-filter-pill ${circleFilter === "sharp" ? "active" : ""}" data-kfilter="sharp">الدييز (♯)</button>
      <button class="k-filter-pill ${circleFilter === "flat" ? "active" : ""}" data-kfilter="flat">البيمول (♭)</button>
    </div>
  `;

  const keyCards = list.map(k => `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag ${k.group === "neutral" ? "tag-sage" : k.group === "sharp" ? "tag-peach" : "tag-lilac"}">${k.sigBadge}</span>
        <span class="k-ratio-chip">${k.majorName} / ${k.minorName}</span>
      </div>
      <h4>${k.majorName} والنسبي ${k.minorName}</h4>
      <p><strong>دليل المقام:</strong> ${k.accidentalList}</p>
      <p><strong>التآلفات الدياتونية:</strong> <code>${k.chords}</code></p>
      <p class="k-tip">${k.instrumentTip}</p>
      <div class="k-btn-row">
        <button class="btn-tool" data-play-key-cadence="${k.rootMidi}" data-key-mode="major">▶ قفلة ${k.majorName}</button>
        <button class="btn-tool" data-play-key-cadence="${k.minorMidi}" data-key-mode="minor">▶ ${k.minorName}</button>
      </div>
    </article>
  `).join("");

  const extraSections = `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">4. الأوجه الثلاثة للسلم الصغير</span>
        <span class="k-ratio-chip">لماذا توجد 3 سلالم صغيرة؟</span>
      </div>
      <h4>الصغير الطبيعي والهارموني واللحني (في A صغير)</h4>
      <p>
        بينما يحتفظ الكبير بصورة واحدة ثابتة، تستخدم الموسيقى في الصغير ثلاث صيغ متكاملة؛ لأن الصغير الطبيعي يفتقر إلى نغمة حساسة أسفل القرار بنصف بُعد (<code>G → A</code> بُعد كامل، ليس بحدة <code>G♯ → A</code>):
      </p>
      <ul class="k-physics-list">
        <li><strong>الصغير الطبيعي (الإيولي):</strong> يأخذ دليل مقام الكبير النسبي كما هو (<code>A–B–C–D–E–F–G–A</code>). شعبي، طبيعي، وسلس.</li>
        <li><strong>الصغير الهارموني:</strong> يرفع الدرجة السابعة (<code>G → G♯</code>) ليصبح تآلف الدرجة الخامسة <strong>مسيطرة كبيرة حقيقية (E7)</strong>، ويولّد قفزة تعبيرية من 3 أنصاف أبعاد بين <code>F</code> و<code>G♯</code>.</li>
        <li><strong>الصغير اللحني:</strong> لتليين تلك القفزة للمغنين، يرفع الدرجة السادسة أيضاً صعوداً (<code>F → F♯, G → G♯</code>)؛ وفي الكلاسيك غالباً ما يعود للصغير الطبيعي هبوطاً بينما يحتفظ الجاز بالصيغة المرفوعة في الاتجاهين.</li>
      </ul>
      <div class="k-btn-row">
        <button class="btn-tool" data-play-inst="true" data-style="piano" data-notes="A3,B3,C4,D4,E4,F4,G4,A4" data-dur="0.45" data-step="320">▶ A صغير طبيعي</button>
        <button class="btn-tool" data-play-inst="true" data-style="piano" data-notes="A3,B3,C4,D4,E4,F4,G#4,A4" data-dur="0.45" data-step="320">▶ A صغير هارموني</button>
        <button class="btn-tool" data-play-inst="true" data-style="piano" data-notes="A3,B3,C4,D4,E4,F#4,G#4,A4" data-dur="0.45" data-step="320">▶ A صغير لحني</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">5. علاقات المقامات والانتقالات (Modulations)</span>
        <span class="k-ratio-chip">تغيير المقام</span>
      </div>
      <h4>كيف تتواصل المقامات وتنتقل بسلاسة؟</h4>
      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>الصغير / الكبير النسبي (بفارق 3 أنصاف أبعاد)</strong>
          يتقاسمان النغمات ودليل المقام نفسه: <code>C كبير ↔ A صغير</code>، <code>G كبير ↔ E صغير</code>. والانتقال من مركز إلى آخر يبدو طبيعياً وسلساً.
        </div>
        <div class="physics-fact-item">
          <strong>الكبير / الصغير الموازي (درجة القرار نفسها)</strong>
          يحتفظان بدرجة القرار نفسها مع تبديل الكبير والصغير: <code>C كبير ↔ C صغير</code> (بفارق 3 بيمولات!). يمنح تحولات درامية مثل «ثالثة بيكاردي» الشهيرة.
        </div>
        <div class="physics-fact-item">
          <strong>المقامات المتقاربة (الجيران في الدائرة)</strong>
          تختلف المقامات المجاورة بخطوة واحدة (<code>C كبير ↔ G</code> أو <code>F</code>) في نغمة واحدة فقط. وتتيح التآلفات المشتركة (المحورية مثل <code>Am</code>) انتقالات خفية سلسة.
        </div>
        <div class="physics-fact-item">
          <strong>الوسائط الكروماتية والانتقال ببُعد كامل</strong>
          الانتقال بمسافة ثالثة (<code>C → Ab</code> أو <code>E</code>) يبدّل عدة علامات تحويل دفعة واحدة لأثر سينمائي ساحر؛ أما الصعود بنصف بُعد أو بُعد كامل في اللازمة الأخيرة فيضاعف الطاقة.
        </div>
      </div>
      <div class="k-btn-row">
        <button class="btn-tool" data-play-custom="key-variant">▶ الموازي C ↔ Cm</button>
        <button class="btn-tool" data-play-custom="key-mediant">▶ وسيط كروماتي C → Ab → C</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">6. الآلات الناقلة للطبقة ولون المقام</span>
        <span class="k-ratio-chip">ممارسة الفرق</span>
      </div>
      <h4>لماذا لا تقرأ آلات النفخ دليل المقام نفسه الذي يقرؤه البيانو؟</h4>
      <p>
        بينما يقرأ البيانو والجيتار والوتريات والفلوت <strong>بدرجة C (الصوت الفعلي)</strong>، صُممت كثير من آلات النفخ الناقلة للطبقة للحفاظ على مواضع الأصابع نفسها عبر الأحجام المختلفة:
      </p>
      <ul class="k-physics-list">
        <li><strong>آلات Bb (الترومبيت، الكلارينيت، التينور ساكسفون):</strong> نغمة <code>C</code> المكتوبة تُسمع فعلياً <code>Bb</code> (أخفض بثانية كبيرة). عندما تعزف الفرقة في <code>Bb كبير (2♭)</code>، يقرأ الترومبيت بسهولة في <code>C كبير (0 علامات)</code>!</li>
        <li><strong>آلات Eb (الألتو ساكسفون، الباريتون ساكسفون):</strong> نغمة <code>C</code> المكتوبة تُسمع فعلياً <code>Eb</code> (أخفض بسادسة كبيرة). وعندما تعزف الفرقة في <code>Eb كبير (3♭)</code>، يقرأ الألتو ساكسفون في <code>C كبير</code>.</li>
        <li><strong>آلات F (الهورن الفرنسي، الكورنو الإنجليزي):</strong> نغمة <code>C</code> المكتوبة تُسمع أخفض بخامسة تامة، أي <code>F</code> الفعلية.</li>
      </ul>
      <p class="k-tip"><strong>«شخصية» المقام:</strong> قبل التعديل المتساوي، كانت فروق الضبط تمنح كل مقام مذاقاً مستقلاً (دفء <em>Db</em>، بريق <em>D</em>). واليوم تتقاسم المقامات الـ 12 النسب الرياضية نفسها، لكن الآلات الحقيقية لا تزال تلوّن كل مقام بطريقتها عبر الأوتار المطلقة ورنين الأنابيب والمدى الصوتي.</p>
    </article>
  `;

  return theoryIntro + `<div class="knowledge-list">${keyCards}</div>` + extraSections;
}

function renderSingAndPlayReferenceHTML_AR() {
  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">1. لماذا يتعثر التنسيق في البداية؟</span>
        <span class="k-ratio-chip">الطيار الآلي والتركيز</span>
      </div>
      <h4>لماذا يبدو الغناء أثناء العزف صعباً للغاية في البداية؟</h4>
      <p>
        لحظة تعزف وتغني في آنٍ واحد، يتقاسم نظامان مستقلان تماماً النبض نفسه: <strong>يداك</strong> (الذاكرة العضلية، مواضع التآلفات، الإيقاع) و<strong>صوتك</strong> (التنفس، الضبط الصوتي، الكلمات). ولا تستطيع الذاكرة العاملة إدارة مهمتين جديدتين بالكامل تحت المجهر في الثانية نفسها.
      </p>
      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>ضع طرفاً واحداً على الأقل في وضع الطيار الآلي</strong>
          ما دام الصوت واليدان يتصادمان، فهذا يعني أن دماغك لا يزال يقود كليهما بوعي كامل. الحل: كرّر المرافقة (أو الخط الغنائي) حتى تنساب تلقائياً مثل صعود السلالم.
        </div>
        <div class="physics-fact-item">
          <strong>ثبّت الإيقاع قبل النغمات</strong>
          90% من التعثرات إيقاعية وليست لحنية! عندما يقع مقطع لفظي بين ضربتين، تتجمد اليدان إلى أن يتطابق الإيقاعان بوضوح.
        </div>
        <div class="physics-fact-item">
          <strong>دندن أولاً على «لا» أو «دو»</strong>
          تذكّر الكلمات يستهلك قدراً هائلاً من الطاقة الذهنية. دندنة اللحن بمقطع محايد واحد يفتح فوراً مساحة للضبط الصوتي والإيقاع.
        </div>
        <div class="physics-fact-item">
          <strong>نبض داخلي واحد مشترك</strong>
          دع نقرة قدم خفيفة أو المترونوم يتولى القيادة: لا الصوت يلاحق اليدين ولا اليدان تنتظران الصوت؛ بل <em>كلاهما</em> يستجيب للنبض نفسه.
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">2. تدريب منهجي في 5 خطوات</span>
        <span class="k-ratio-chip">منهج خطوة بخطوة</span>
      </div>
      <h4>الروتين المثبت من 5 خطوات لأي أغنية</h4>
      <p>
        بدلاً من البدء دوماً من المازورة الأولى والتعثر عند الموضع نفسه، قسّم التنسيق بإيجاز إلى خمس خطوات عملية:
      </p>
      <ul class="article-steps-list">
        <li>
          <strong>1. اختبار المحادثة (أتمتة اليدين):</strong> كرّر المرافقة في حلقة لمدة 1–2 دقيقة حتى تتمكن من العد بصوت عالٍ حتى 20 أو التحدث بأريحية أثناء العزف. إن توقفت يداك عند الكلام، امنح الآلة 5 دقائق منفردة إضافية.
        </li>
        <li>
          <strong>2. إلقاء الكلمات على الإيقاع:</strong> أثناء عزف تآلفاتك، <strong>اقرأ الكلمات بصوت كلام عادي وبدقة إيقاعية تامة</strong>. إزالة اللحن تكشف فوراً أي المقاطع تقع على النبضات وأيها تقع بينها.
        </li>
        <li>
          <strong>3. تحديد نقاط الالتقاء الجسدية:</strong> ضع علامات واضحة: <em>«الإبهام يضرب الباص مع كلمة “ليل”»</em> أو <em>«كلمة “حر” تقع على الضربة الصاعدة بين 2 و3»</em>. يرتبط الدماغ بسهولة بنقاط الارتكاز الملموسة!
        </li>
        <li>
          <strong>4. بسّط التآلفات وكرّر مازورة أو مازورتين:</strong> ابدأ حرفياً بـ<strong>تآلف واحد ممتد على النبضة 1 فقط</strong> وغنِّ فوقه بحرية. وعندما يستقر، أضف النبضة 3 ثم استعد الإيقاع الكامل — دائماً في حلقات صغيرة من مازورة إلى مازورتين!
        </li>
        <li>
          <strong>5. الحركة البطيئة (60%) و«الغناء الشبح»:</strong> اخفض السرعة إلى النصف تقريباً. في المداخل الصعبة، حرّك شفتيك باللحن صمتاً أو اسمعه داخلياً خلال دورة، ثم دندنه في الدورة التالية، ثم غنّه بثقة.
        </li>
      </ul>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">3. تمارين الاستقلالية اليومية</span>
        <span class="k-ratio-chip">جرّب الآن</span>
      </div>
      <h4>6 تمارين عملية للتنسيق والاستقلالية</h4>
      <p>
        خمس إلى ثماني دقائق مع تمرين أو اثنين من هذه التمارين قبل أغنياتك تمنحك استقلالية أسرع بكثير من التكرار العشوائي:
      </p>
      <ul class="k-physics-list">
        <li>
          <strong>التمرين 1 – اختبار الكلام والعد:</strong> اعزف تتابعاً سلساً من أربعة تآلفات (<code>I – V – vi – IV</code>) بإيقاع منتظم بينما تقرأ نصاً قصيراً بصوت عالٍ أو تعد تنازلياً من 20 إلى 1. القاعدة: لا يجوز للإيقاع أن يختل ملليمتراً واحداً.
        </li>
        <li>
          <strong>التمرين 2 – تآلفات النبضة الأولى:</strong> اعزف كل تآلف مرة واحدة فقط على النبضة 1 (كنغمة مستديرة ممتدة) وغنِّ المقطع كاملاً فوق هذا الرنين المفتوح. يطوّر التعبير وإدارة التنفس وانتقال التآلفات بهدوء.
        </li>
        <li>
          <strong>التمرين 3 – نغمة قرار بخامسة ثابتة (Drone):</strong> أبقِ على قرار + خامسة بسيطة (<code>C3 + G3</code>) على آلتك وغنِّ فوقها ألحاناً أو مسافات. يدرب الأذن دون إرهاق اليد اليسرى.
        </li>
        <li>
          <strong>التمرين 4 – المداخل المبكرة وفخ «4-و»:</strong> في البوب والسول يدخل الغناء غالباً <em>مبكراً</em> بنصف نبضة (على <code>4-و</code>) بينما يتغير الجيتار أو البيانو على النبضة 1 تماماً. انقر نبضات ربع منتظمة بينما تبدأ الجملة الغنائية على «و».
        </li>
        <li>
          <strong>التمرين 5 – باص متحرك مقابل نغمة غنائية ثابتة:</strong> عزّز خط باص بسيطاً متحركاً (مثل <code>C – F – G – C</code>) بينما يثبت صوتك على نغمة مشتركة واحدة (<code>G</code>) — أو اعكس الأمر: ثبّت تآلفاً واحداً وغنِّ سلماً صعوداً وهبوطاً.
        </li>
        <li>
          <strong>التمرين 6 – فحص الـ 20 ثانية بالهاتف:</strong> سجّل حلقة قصيرة بهاتفك واستمع إليها فوراً. سماع نفسك من الخارج يكشف النبضات الضائعة أو التسارع في اللحظة نفسها.
        </li>
      </ul>
      <div class="k-btn-row">
        <button class="btn-tool" data-play-progression="I,V,vi,IV">▶ تمرين 1: إيقاع للتحدث فوقه</button>
        <button class="btn-tool" data-play-custom="sp-drone">▶ تمرين 3: قرار ثابت + لحن</button>
        <button class="btn-tool" data-play-custom="sp-syncopation">▶ تمرين 4: النبض مقابل الدخول المبكر</button>
        <button class="btn-tool" data-play-custom="sp-poly">▶ تمرين 5: باص متحرك، نغمة ثابتة</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">4. نصائح خاصة بالآلات والأخطاء الشائعة</span>
        <span class="k-ratio-chip">الجيتار، البيانو والصوت</span>
      </div>
      <h4>نصائح عملية توفر عليك أسابيع من المحاولات</h4>
      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>الجيتار: لا توقف البندول أبداً</strong>
          ساعدك الأيمن مترونوم لا يتوقف (<em>أسفل – أعلى – أسفل – أعلى</em>). حتى في السكتات أو السنكوب الغنائي، لا توقف ذراعك أبداً: مرّرها في الهواء فوق الأوتار دون لمسها.
        </div>
        <div class="physics-fact-item">
          <strong>البيانو: أضف الإيقاعات طبقة تلو الأخرى</strong>
          ابدأ فقط بـ<em>نغمات أساس باليد اليسرى على النبضة 1 + الغناء</em>. ثم أضف تآلفات هادئة باليد اليمنى على 1 و3. واترك الأربيجات الكثيفة والألحان المضادة للخطوة الأخيرة.
        </div>
        <div class="physics-fact-item">
          <strong>انقل الطبقة إلى مدى صوتي مريح</strong>
          الإجهاد في النغمات الحادة يدمّر تنسيق اليدين فوراً. لا تتردد أبداً في استخدام <strong>الكابو (Capo)</strong> أو النقل بمقدار ±2 نصف بُعد لينساب صوتك بأريحية.
        </div>
        <div class="physics-fact-item">
          <strong>خطط للتنفس كأنه نغمة موسيقية</strong>
          تحدث التعثرات غالباً بين الجمل وليس وسط المازورة! احجز بوعي ربع نبضة للشهيق قبل اللازمة بينما تواصل الآلة انسيابها بهدوء.
        </div>
      </div>
      <p class="k-tip"><strong>نصيحة إضافية من Lauscher:</strong> في وحدتي <strong>الصولفيج</strong> و<strong>الألحان</strong> داخل Lauscher، جرّب غناء النغمة المطلوبة بصوت عالٍ <em>قبل</em> الضغط على المفتاح: هكذا تربط الأذن والصوت والأصابع في رد فعل واحد.</p>
    </article>
  `;
}

function renderCircleOfFifthsTheoryHTML_AR() {
  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">1. الفكرة الكبرى</span>
        <span class="k-ratio-chip">3:2 • 12 مقاماً</span>
      </div>
      <h4>ما هي دائرة الخامسات، ولماذا هي دائرة؟</h4>
      <p>
        مباشرة بعد الأوكتاف (<code>2:1</code>)، تُعد <strong>الخامسة التامة (3:2)</strong> أقوى رابط صوتي في الموسيقى. اصعد بخامسات متتالية بدءاً من <strong>C</strong> (<code>C → G → D → A → E → B → F♯…</code>): في كل خطوة ترتفع نغمة واحدة لصنع النغمة الحساسة الجديدة، فتُضاف <strong>علامة دييز (♯)</strong> واحدة مع عقارب الساعة. واهبط بخامسات (أي اصعد <strong>برابعات</strong>: <code>C → F → B♭ → E♭ → A♭ → D♭ → G♭</code>): يزداد اللون دفئاً وتُضاف <strong>علامة بيمول (♭)</strong> واحدة عكس عقارب الساعة.
      </p>
      <p>
        بعد 6 خطوات في كل اتجاه يلتقي جانب الدييز وجانب البيمول عند <strong>الساعة 6 (F♯ / G♭)</strong>، حيث تقع في التعديل المتساوي 6 علامات دييز و6 علامات بيمول على مفاتيح البيانو نفسها تماماً. وبعد 12 خامسة تعود إلى C (<strong>الترادف الإنهارموني</strong>). وبدلاً من حفظ 12 سلماً منفصلاً، تمتلك بوصلة موسيقية واحدة!
      </p>
      <div class="k-compare-grid">
        <div class="k-compare-box is-peach">
          <h5>مع عقارب الساعة (+1 ♯) • خامسات صاعدة</h5>
          <p><code>C → G → D → A → E → B → F♯</code><br>يزداد الإشراق خطوة بعد خطوة. ترتيب الدييز: <code>F♯ – C♯ – G♯ – D♯ – A♯ – E♯</code>.</p>
        </div>
        <div class="k-compare-box is-lilac">
          <h5>عكس عقارب الساعة (+1 ♭) • رابعات صاعدة</h5>
          <p><code>C → F → B♭ → E♭ → A♭ → D♭ → G♭</code><br>يزداد اللون دفئاً ونعومة. ترتيب البيمول معاكس تماماً: <code>B♭ – E♭ – A♭ – D♭ – G♭ – C♭</code>.</p>
        </div>
      </div>
    </article>

    <details class="knowledge-card k-accordion">
      <summary class="k-accordion-summary">
        <div class="k-accordion-head">
          <div class="k-card-top-row">
            <span class="k-card-tag tag-peach">2. دليل الاستخدام</span>
            <span class="k-ratio-chip">منطق الساعة</span>
          </div>
          <h4>كيف تقرأ العجلة وتستخدمها في 20 ثانية</h4>
        </div>
        <span class="k-accordion-chevron" aria-hidden="true">⌄</span>
      </summary>
      <div class="k-accordion-body">
        <ul class="k-physics-list">
          <li><strong>الحلقة الخارجية = الكبير، والحلقة الداخلية = الصغير النسبي:</strong> يقرن كل قطاع مقاماً كبيراً بـ<strong>صغيره النسبي</strong> أسفله مباشرة (<code>C / Am</code>، <code>G / Em</code>، <code>D / Bm</code>…). ويتقاسم الاثنان <em>النغمات السبع نفسها ودليل المقام نفسه</em>: ينقل الصغير المركز 3 أنصاف أبعاد للأسفل فقط (الدرجة 6 / <em>La</em>).</li>
          <li><strong>الحيلة السريعة لمقامات الدييز:</strong> انظر إلى <em>آخر دييز</em> في دليل المقام واصعد <strong>نصف بُعد واحد</strong>: ها قد وصلت إلى درجة القرار الكبيرة! (مثال: 2 دييز <code>F♯, C♯</code> ← نصف بُعد فوق <code>C♯</code> = <strong>D كبير</strong>).</li>
          <li><strong>الحيلة السريعة لمقامات البيمول:</strong> <em>البيمول قبل الأخير</em> في دليل المقام يمنحك اسم المقام الكبير مباشرة! (مثال: 3 بيمول <code>B♭, E♭, A♭</code> ← قبل الأخير هو <strong>E♭ كبير</strong>؛ ويُحفظ <code>1♭ = F كبير</code> بمفرده).</li>
          <li><strong>اقرأ اليسار والوسط واليمين كالبوصلة:</strong> أي قطاع تختاره يصبح <code>I</code> (درجة القرار). جاره الأيسر هو دائماً <strong>تحت المسيطرة (IV)</strong>، وجاره الأيمن هو دائماً <strong>المسيطرة (V)</strong>!</li>
        </ul>
      </div>
    </details>

    <details class="knowledge-card k-accordion">
      <summary class="k-accordion-summary">
        <div class="k-accordion-head">
          <div class="k-card-top-row">
            <span class="k-card-tag tag-lilac">3. قوة موسيقية خارقة</span>
            <span class="k-ratio-chip">تطبيقات عملية</span>
          </div>
          <h4>ما الذي يتحسن فعلياً حين تتقن الدائرة؟</h4>
        </div>
        <span class="k-accordion-chevron" aria-hidden="true">⌄</span>
      </summary>
      <div class="k-accordion-body">
        <div class="physics-fact-grid">
          <div class="physics-fact-item">
            <strong>1. خريطة فورية لتآلفات المقام</strong>
            انظر إلى القطاعات الثلاثة المضاءة أعلاه: تجمع درجة القرار وجاراها المباشران <strong>التآلفات الدياتونية الستة الرئيسية</strong> للمقام (<code>IV – I – V</code> في الخارج + <code>ii – vi – iii</code> في الداخل)! وتعيش آلاف أغاني البوب والروك والفولك داخل هذه الشريحة وحدها.
          </div>
          <div class="physics-fact-item">
            <strong>2. النقل المقامي (Transpose) بلا حساب ذهني</strong>
            الطبقة حادة جداً للغناء؟ أدر هذه الكتلة ذات القطاعات الثلاثة حول القرص: تبقى العلاقات كلها مطابقة (<code>I–V–vi–IV</code> في C تصبح بخطوة واحدة <code>G–D–Em–C</code>، أو بالتحرك يساراً <code>F–C–Dm–B♭</code>).
          </div>
          <div class="physics-fact-item">
            <strong>3. انتقالات سلسة وتحولات مفاجئة</strong>
            يختلف القطاعان المتجاوران في <strong>نغمة واحدة فقط</strong> (6 نغمات مشتركة من أصل 7!)، مما يمنح انتقالات حريرية بين المقطع واللازمة. أما القفز إلى الجهة المقابلة تماماً (6 خطوات / الترايتون) فيجدد معظم النغمات لأقصى أثر درامي.
          </div>
          <div class="physics-fact-item">
            <strong>4. أذن هارمونية وقراءة أسرع</strong>
            لاحظ كيف تسير تتابعات الجاز والبوب الشهيرة (<code>iii – vi – ii – V – I</code>) خطوة بخطوة <em>عكس عقارب الساعة</em> حول العجلة! فتبدأ أذنك بتوقع النغمة الأساسية التالية هندسياً بدلاً من التخمين.
          </div>
        </div>
      </div>
    </details>

    <details class="knowledge-card k-accordion">
      <summary class="k-accordion-summary">
        <div class="k-accordion-head">
          <div class="k-card-top-row">
            <span class="k-card-tag tag-sage">4. تمارين تطبيقية</span>
            <span class="k-ratio-chip">العزف والاستماع</span>
          </div>
          <h4>4 طرق عملية عالية الأثر للتدرب على الدائرة</h4>
        </div>
        <span class="k-accordion-chevron" aria-hidden="true">⌄</span>
      </summary>
      <div class="k-accordion-body">
        <ul class="k-physics-list">
          <li><strong>تحرر من عادة «C وG فقط»:</strong> خذ أي جملة أو سلم أو تتابع وحرّكه يومياً خطوة واحدة مع عقارب الساعة (<code>C → G → D → A</code>) أو عكسها عبر مقامات النفخ (<code>F → B♭ → E♭ → A♭</code>). خلال 12 يوماً تكون قد أتقنت لوحة المفاتيح أو رقبة الجيتار كاملة.</li>
          <li><strong>استمع لتتابعات الخامسات (<code>vi–ii–V–I</code>):</strong> عُد تدريجياً نحو الساعة 12: يتصرف كل تآلف كمسيطرة صغيرة تجذبك إلى القطاع التالي! اضغط أدناه لسماع هذه الجاذبية المغناطيسية في C كبير.</li>
          <li><strong>استعر لوناً من الجار (المسيطرات الثانوية):</strong> هل تريد دفعاً أقوى قبل <code>G (V)</code> في C كبير؟ استعر <code>F♯</code> من الجار الأيمن لتحويل <code>ii (Dm)</code> الصغير إلى <strong>D7 (V/V)</strong> مشرق يشير مباشرة نحو G.</li>
          <li><strong>قارن بين الدفء والاندفاع المشرق:</strong> التحرك يساراً في الدائرة (<code>I → IV → bVII</code>) يمنح أساساً دافئاً وراسخاً؛ أما الصعود يميناً (<code>I → V → V/V</code>) فيضاعف الحماس والإشراق.</li>
        </ul>
        <div class="k-btn-row">
          <button class="btn-tool" data-play-progression="vi,ii,V7,I">▶ استمع لجاذبية الدائرة (Am–Dm–G7–C)</button>
          <button class="btn-tool" data-play-progression="I,V/V,V,I">▶ استمع للاندفاع مع عقارب الساعة (C–D (V/V)–G–C)</button>
        </div>
      </div>
    </details>
  `;
}

function getIntervalNamingGuideHTML_AR() {
  const useGerman = typeof state !== "undefined" ? state?.profile?.intervalNotation !== "intl" : true;
  const schemeBadge = useGerman ? "النشط: P / G / k" : "النشط: P / M / m";
  const m2 = typeof formatIntervalSymbol === "function" ? formatIntervalSymbol("m2") : "m2";
  const M2 = typeof formatIntervalSymbol === "function" ? formatIntervalSymbol("M2") : "M2";
  const m3 = typeof formatIntervalSymbol === "function" ? formatIntervalSymbol("m3") : "m3";
  const M3 = typeof formatIntervalSymbol === "function" ? formatIntervalSymbol("M3") : "M3";
  return `
    <details class="knowledge-card k-accordion" id="intervalNamingGuideAccordion" open>
      <summary class="k-accordion-summary">
        <div class="k-accordion-head">
          <div class="k-card-top-row">
            <span class="k-card-tag tag-sage">الاختصارات والأسماء</span>
            <span class="k-ratio-chip">${schemeBadge}</span>
          </div>
          <h4>كيف تقرأ الرموز المختصرة للمسافات (حرف + رقم)؟</h4>
        </div>
        <span class="k-accordion-chevron" aria-hidden="true">⌄</span>
      </summary>
      <div class="k-accordion-body">
        <p>يجمع كل رمز مسافة معلومتين في محرفين: يحدد <strong>الرقم</strong> عدد درجات السلم التي يغطيها، ويحدد <strong>الحرف</strong> العرض الدقيق بأنصاف الأبعاد.</p>
        <ul class="k-physics-list">
          <li><strong>1. الرقم (<code>1</code>–<code>9</code>) يعدّ أسماء النغمات:</strong> <code>1</code> = تطابق (النغمة نفسها)، <code>2</code> = ثانية، <code>3</code> = ثالثة، <code>4</code> = رابعة، <code>5</code> = خامسة، <code>6</code> = سادسة، <code>7</code> = سابعة، <code>8</code> = أوكتاف، و<code>9</code> = تاسعة.</li>
          <li><strong>2. المسافات التامة (<code>P</code>):</strong> توجد <code>P1</code> و<code>P4</code> و<code>P5</code> و<code>P8</code> في صورة صافية واحدة فقط (<em>Perfect</em> / تامة): بلا تنويع كبير أو صغير.</li>
          <li><strong>3. أزواج الكبير والصغير (<code>2</code>، <code>3</code>، <code>6</code>، <code>7</code>، <code>9</code>):</strong> تأتي هذه المسافات الخمس بلونين يختلفان بـ<strong>نصف بُعد واحد</strong>:<br>
            – <strong>النظام الدولي (<code>P / M / m</code>):</strong> الحرف الكبير <strong><code>M</code></strong> (<em>Major</em> / كبير) للمسافة الأوسع والأكثر إشراقاً؛ والحرف الصغير <strong><code>m</code></strong> (<em>minor</em> / صغير) للمسافة الأضيق بنصف بُعد (مثل <code>M3</code> مقابل <code>m3</code>). حالة الحرف حاسمة هنا!<br>
            – <strong>النظام الألماني (<code>P / G / k</code>):</strong> الحرف الكبير <strong><code>G</code></strong> (<em>Groß</em> = كبير) مقابل الحرف الصغير <strong><code>k</code></strong> (<em>klein</em> = صغير، مثل <code>G3</code> مقابل <code>k3</code>).</li>
          <li><strong>4. الترايتون (<code>TT</code>):</strong> يشطر الأوكتاف تماماً من المنتصف عند <strong>6 أنصاف أبعاد</strong>، بين <code>P4</code> و<code>P5</code> مباشرة (رابعة زائدة / خامسة ناقصة).</li>
        </ul>
        <div class="k-meta-box">
          <div><strong>الرموز النشطة:</strong> الثانيات: <code>${m2}</code> (1 نصف بُعد) مقابل <code>${M2}</code> (2 نصف بُعد) · الثالثات: <code>${m3}</code> (3 أنصاف) مقابل <code>${M3}</code> (4 أنصاف)</div>
          <div><strong>التخصيص:</strong> بدّل في أي وقت بين <strong>الدولي (P / M / m)</strong> و<strong>الألماني (P / G / k)</strong> من <strong>الإعدادات → التدوين الموسيقي → تسمية المسافات</strong>.</div>
        </div>
      </div>
    </details>
  `;
}

function renderNotationReferenceHTML_AR() {
  const staffFn = typeof buildNotationKnowledgeStaffSVG === "function" ? buildNotationKnowledgeStaffSVG : null;
  const trebleAnchorSvg = staffFn ? staffFn("treble", [0, 2, 4, 6, 8], { width: 290, highlightAnchorLine: true, showLabels: true, labelShort: true }) : "";
  const bassAnchorSvg = staffFn ? staffFn("bass", [0, 2, 4, 6, 8], { width: 290, highlightAnchorLine: true, showLabels: true, labelShort: true }) : "";
  const altoAnchorSvg = staffFn ? staffFn("alto", [0, 2, 4, 6, 8], { width: 290, highlightAnchorLine: true, showLabels: true, labelShort: true }) : "";
  const ledgerSvg = staffFn ? staffFn("treble", [-6, -4, -2, 4, 10, 12, 14], { width: 340, showLabels: true, labelShort: true }) : "";
  const ledgerBassSvg = staffFn ? staffFn("bass", [-6, -4, -2, 4, 10, 12, 14], { width: 340, showLabels: true, labelShort: true }) : "";
  const accSvg = staffFn ? staffFn("treble", [
    { step: 1, accidental: 0 },
    { step: 1, accidental: 1 },
    { step: 2, accidental: -1 },
    { step: 6, accidental: 0 },
    { step: 6, accidental: -1 }
  ], { width: 320, showLabels: true, labelShort: true }) : "";
  const keySigSharpSvg = staffFn ? staffFn("treble", [
    { step: 1, accidental: 1 },
    { step: 5, accidental: 1 },
    { step: 1, accidental: 0 }
  ], { width: 300, keySignatureId: "D", showLabels: true, labelShort: true }) : "";
  const keySigFlatSvg = staffFn ? staffFn("treble", [
    { step: 4, accidental: -1 },
    { step: 7, accidental: -1 },
    { step: 2, accidental: 0 }
  ], { width: 300, keySignatureId: "Eb", showLabels: true, labelShort: true }) : "";

  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">1. المدرج الموسيقي ذو الخطوط الخمسة</span>
        <span class="k-ratio-chip">الخطوط والمسافات</span>
      </div>
      <h4>كيف تُقرأ الموسيقى على الورق؟</h4>
      <p>
        يعمل التدوين الموسيقي كنظام إحداثيات: يمثل <strong>المحور العمودي</strong> الطبقة الصوتية (الأعلى = أحدّ، والأسفل = أعمق)، بينما يمثل <strong>المحور الأفقي</strong> الزمن المتدفق من اليسار إلى اليمين.
      </p>
      <ul class="k-physics-list">
        <li><strong>عدّ دائماً من الأسفل إلى الأعلى:</strong> يتكوّن المدرج الموسيقي من <strong>5 خطوط</strong> (من الخط 1 في الأسفل إلى الخط 5 في الأعلى) وبينها <strong>4 مسافات</strong>.</li>
        <li><strong>التناوب بين خط ومسافة:</strong> الانتقال من أي خط إلى المسافة الملاصقة له يعني دائماً الصعود أو الهبوط <strong>درجةً دياتونية واحدة</strong> (<code>C → D → E → F → G → A → B</code>).</li>
        <li><strong>لماذا يُعد المفتاح ضرورياً:</strong> دون مفتاح تبقى الخطوط صامتة: فالمفتاح هو الذي يثبّت <em>نغمة مرجعية دقيقة</em> على أحد الخطوط فتنتظم بقية النغمات تلقائياً.</li>
      </ul>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">2. المفاتيح الثلاثة الرئيسية (والمفاتيح الخاصة)</span>
        <span class="k-ratio-chip">صول • فا • دو (الألتو)</span>
      </div>
      <h4>ثلاث نوافذ على لوحة المفاتيح نفسها</h4>
      <p>
        يُظهر الخط المضاء بالبرتقالي <strong>نقطة الارتكاز المرجعية</strong> لكل مفتاح. احفظ هذا المرجع الوحيد لتستنتج كل الخطوط والمسافات المجاورة بسرعة.
      </p>
      <div class="notation-knowledge-grid">
        <div class="notation-knowledge-card">
          ${trebleAnchorSvg}
          <h5>مفتاح صول (G Clef)</h5>
          <p>يلتف حلزونه الأوسط حول <strong>الخط الثاني من الأسفل = G4</strong>. وهو المعيار للغناء (سوبرانو/ألتو)، والكمان، والفلوت، والترومبيت، والجيتار، واليد اليمنى للبيانو.</p>
          <p><strong>مرجع سريع (من الأسفل للأعلى):</strong> الخطوط <em>E – G – B – D – F</em>؛ والمسافات <em>F – A – C – E</em>.</p>
          <button type="button" class="btn-tool" data-play-solo-note="G4">▶ استمع لمرجع G4</button>
        </div>
        <div class="notation-knowledge-card">
          ${bassAnchorSvg}
          <h5>مفتاح فا (F Clef)</h5>
          <p>تحيط نقطتاه بـ<strong>الخط الرابع من الأسفل = F3</strong>. لا غنى عنه لليد اليسرى للبيانو، والتشيلو، والكونتراباص، وجيتار الباص، والترومبون، والأصوات الجهيرة.</p>
          <p><strong>مرجع سريع (من الأسفل للأعلى):</strong> الخطوط <em>G – B – D – F – A</em>؛ والمسافات <em>A – C – E – G</em>.</p>
          <button type="button" class="btn-tool" data-play-solo-note="F3">▶ استمع لمرجع F3</button>
        </div>
        <div class="notation-knowledge-card">
          ${altoAnchorSvg}
          <h5>مفتاح الألتو / دو (الخط الثالث)</h5>
          <p>يشير منتصفه تماماً إلى <strong>الخط الثالث (الأوسط) = دو الوسطى (C4)</strong>. وهو المفتاح الطبيعي للفيولا في الأوركسترا والعديد من المدونات متعددة الأصوات.</p>
          <p><strong>حيلة التماثل:</strong> فوق <code>C4</code> الوسطى تقع <em>E</em> (الرابع) و<em>G</em> (الخامس)، وتحتها مباشرة تقع <em>A</em> (الثاني) و<em>F</em> (الأول).</p>
          <button type="button" class="btn-tool" data-play-solo-note="C4">▶ استمع لمرجع C4</button>
        </div>
      </div>

      <div class="k-meta-box">
        <div><strong>دو الوسطى (C4) نفسها تربط المفاتيح الثلاثة:</strong> في <strong>مفتاح صول</strong> تقع على الخط الإضافي الأول <em>أسفل</em> المدرج؛ وفي <strong>مفتاح الألتو</strong> في <em>المنتصف تماماً (الخط 3)</em>؛ وفي <strong>مفتاح فا</strong> على الخط الإضافي الأول <em>أعلى</em> المدرج.</div>
        <div><strong>المفاتيح الخاصة (نظرة سريعة):</strong> يضع <strong>مفتاح التينور (دو على الخط الرابع)</strong> دو الوسطى على الخط الرابع لمقاطع التشيلو والباصون والترومبون العالية؛ أما مفاتيح الأوكتاف (<code>8vb</code> / <code>8va</code>) فتجنّب الجيتار والبيكولو تكدس الخطوط الإضافية.</div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">3. حتى 3 خطوط إضافية</span>
        <span class="k-ratio-chip">±3 خطوط إضافية</span>
      </div>
      <h4>القراءة أعلى وأسفل المدرج دون عدٍّ بطيء</h4>
      <p>
        عندما تتجاوز النغمات الخطوط الخمسة، تمدّد خطوط قصيرة تُسمى <strong>الخطوط الإضافية (Ledger Lines)</strong> المدرجَ موضعياً. هنا تتدرب حتى <strong>3 خطوط إضافية صعوداً وهبوطاً</strong> — وهو المدى الفعلي لمدونات الأوركسترا والبيانو.
      </p>
      <div class="notation-knowledge-grid">
        <div class="notation-knowledge-card">
          ${ledgerSvg}
          <h5>مفتاح صول: ±3 خطوط إضافية</h5>
          <p>يساراً: الخطوط الإضافية 3 و2 و1 في الأسفل (<code>F3 – A3 – C4</code>)؛ في الوسط: <code>B4</code>؛ يميناً: الخطوط الإضافية 1 و2 و3 في الأعلى (<code>A5 – C6 – E6</code>).</p>
        </div>
        <div class="notation-knowledge-card">
          ${ledgerBassSvg}
          <h5>مفتاح فا: العمق الجهير والمدى اللحني العالي</h5>
          <p>في الأسفل: تهبط 3 خطوط إضافية حتى <code>A1</code>؛ وفي الأعلى: تصعد عبر دو الوسطى (<code>C4</code>) إلى <code>E4</code> و<code>G4</code>.</p>
        </div>
      </div>
      <ul class="k-physics-list">
        <li><strong>احفظ نقطتي ارتكاز خارج المدرج:</strong> ثبّت الخط الإضافي الأول والثاني في ذهنك (مثل <code>C4</code> و<code>A3</code> أسفل مفتاح صول، و<code>A5</code> و<code>C6</code> أعلاه) لتتعرف فوراً على كل درجة مجاورة.</li>
        <li><strong>انتبه لقفزات الثالثة:</strong> الانتقال من خط إضافي إلى الخط الإضافي التالي مباشرة يقفز دائماً مسافة <strong>ثالثة</strong> (بنفس مبدأ تكديس التآلفات).</li>
      </ul>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">4. علامات التحويل وأنظمة التسمية</span>
        <span class="k-ratio-chip">♯ • ♭ • B مقابل H</span>
      </div>
      <h4>المفاتيح السوداء، الترادف الإنهارموني، والفارق الألماني</h4>
      <div class="notation-knowledge-grid">
        <div class="notation-knowledge-card">
          ${accSvg}
          <div class="k-btn-row" style="margin-top:0.25rem;">
            <button type="button" class="btn-tool" data-play-solo-note="F4">▶ F4</button>
            <button type="button" class="btn-tool" data-play-solo-note="F#4">▶ F♯4 / G♭4</button>
            <button type="button" class="btn-tool" data-play-solo-note="Bb4">▶ B♭4</button>
          </div>
        </div>
        <div class="notation-knowledge-card">
          <ul class="k-physics-list">
            <li><strong>الدييز (<code>♯</code>):</strong> يرفع النغمة <strong>نصف بُعد واحد</strong> (المفتاح الأيمن). فتصبح <code>F</code> ← <code>F♯</code>.</li>
            <li><strong>البيمول (<code>♭</code>):</strong> يخفض النغمة <strong>نصف بُعد واحد</strong> (المفتاح الأيسر). فتصبح <code>G</code> ← <code>G♭</code>.</li>
            <li><strong>الترادف الإنهارموني:</strong> على البيانو، <code>F♯</code> و<code>G♭</code> هما المفتاح الأسود نفسه تماماً، وتتغيّر الكتابة فقط تبعاً للوظيفة الهارمونية.</li>
            <li><strong>انتبه للتدوين الألماني:</strong> في التدوين الألماني يُكتب مفتاح <em>B</em> الأبيض بالحرف <strong>H</strong>، بينما تُكتب <em>B♭</em> بالحرف <strong>B</strong>! يمكنك التبديل بين النظامين بسهولة في <em>إعدادات التطبيق</em>.</li>
          </ul>
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">5. دليل المقام والقراءة الفورية</span>
        <span class="k-ratio-chip">دليل ♯/♭ + ♮</span>
      </div>
      <h4>عندما تسري علامات التحويل على المدرج بأكمله</h4>
      <p>
        بدلاً من تكرار كتابة <code>♯</code> أو <code>♭</code> أمام كل نغمة، يوضع دليل المقام <strong>بجانب المفتاح مباشرة</strong> ليعدّل تلك الدرجات تلقائياً في <strong>جميع الأوكتافات</strong> حتى تظهر علامة بيكار (<code>♮</code>) تلغيه.
      </p>
      <div class="notation-knowledge-grid">
        <div class="notation-knowledge-card">
          ${keySigSharpSvg}
          <h5>مقامات الدييز (الترتيب: F – C – G – D – A – E)</h5>
          <p>في <strong>D كبير (2♯)</strong> تصبح كل <code>F</code> ← <code>F♯</code> وكل <code>C</code> ← <code>C♯</code>؛ وعلامة البيكار (<code>♮</code>) أمام النغمة الثالثة وحدها تعيد F الطبيعية.</p>
        </div>
        <div class="notation-knowledge-card">
          ${keySigFlatSvg}
          <h5>مقامات البيمول (الترتيب: B – E – A – D – G – C)</h5>
          <p>في <strong>E♭ كبير (3♭)</strong> تحكم <code>B♭</code> و<code>E♭</code> و<code>A♭</code> المدرج منذ البداية حتى تلغيها علامة بيكار (<code>♮</code>) محتملة.</p>
        </div>
      </div>
    </article>
  `;
}

function renderArrangingReferenceHTML_AR() {
  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">1. ما هو التوزيع الموسيقي (Arranging)؟</span>
        <span class="k-ratio-chip">من المسودة إلى القطعة الكاملة</span>
      </div>
      <h4>فن تحويل فكرة موسيقية إلى عالم صوتي حي</h4>
      <p>
        إذا كان <strong>التأليف</strong> هو المخطط الأولي للأغنية (اللحن، التآلفات الأساسية، والكلمات)، فإن <strong>التوزيع الموسيقي (Arranging)</strong> هو معمارها وإضاءتها ولوحة ألوانها بالكامل: <em>من يعزف ماذا، ومتى، وفي أي أوكتاف، وبأي إيقاع، وبأي ديناميكية، وبأي لون صوتي؟</em>
      </p>
      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>الآلات والألوان الصوتية</strong>
          اختيار الآلات أو الأصوات التي ستحمل اللحن الرئيسي، والباص، والبساط الهارموني، والإيقاع، وكيف ستتمازج ألوانها معاً.
        </div>
        <div class="physics-fact-item">
          <strong>القالب والقوس الدرامي</strong>
          بناء الرحلة العاطفية من مقدمة حميمية إلى اللازمة والجسر والختام.
        </div>
        <div class="physics-fact-item">
          <strong>المناطق الصوتية وتوزيع التآلفات (Voicing)</strong>
          توزيع النغمات من الباص العميق إلى الترددات العليا البلورية كي تتنفس كل آلة دون أن تخنق غيرها.
        </div>
        <div class="physics-fact-item">
          <strong>الحوار والملمس والسكتات</strong>
          تحديد متى يعزف الجميع معاً (<em>Tutti</em>)، وأي آلة تجيب في فراغات الغناء، وأين يصنع الصمت لحظة قشعريرة.
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">2. الوظيفة ومجالات الاستخدام</span>
        <span class="k-ratio-chip">لماذا نوزّع؟</span>
      </div>
      <h4>ما فائدة التوزيع الموسيقي وأين يُستخدم؟</h4>
      <p>
        يمكن للأغنية نفسها بالتآلفات الأربعة نفسها أن تصبح <strong>بالاد بيانو حميمياً</strong>، أو <strong>مقطوعة فانك متقدة</strong>، أو <strong>كورال أكابيلا رباعي الأصوات</strong>، أو <strong>لوحة أوركسترالية سينمائية</strong>:
      </p>
      <ul class="article-steps-list">
        <li><strong>1. توجيه انتباه الأذن:</strong> لا تستطيع الأذن البشرية تتبع أكثر من <strong>طبقتين أو ثلاث طبقات صوتية</strong> بوعي في اللحظة نفسها. التوزيع الجيد يترك المنطقة الوسطى مفتوحة للغناء أو اللحن الرئيسي.</li>
        <li><strong>2. ترجمة الشعور والأسلوب:</strong> يمنح بساط الوتريات دفئاً واتساعاً، وتضخ ضربات النحاسيات القصيرة قوة، بينما يخلق الجيتار الأكوستيك حميمية قريبة.</li>
        <li><strong>3. تجنّب إجهاد الاستماع:</strong> إذا عزفت كل الآلات منذ المازورة الأولى، تتشبع الأذن سريعاً. إضافة الطبقات وسحبها يُبقي كل مقطع ولازمة متجددين.</li>
        <li><strong>4. تكييف الموسيقى مع فرقة حقيقية:</strong> فرقة روك، رباعي وتري، كورال SATB، بيغ باند أو بيانو منفرد: يشكّل التوزيع الكتابة وفق الآلات والمدى الصوتي المتاح.</li>
        <li><strong>5. صياغة الانتقالات بعناية:</strong> فواصل الدرامز، وممرات الباص، والكريشيندو، والتوقفات المفاجئة (<em>Breaks</em>) تربط المقاطع بسلاسة.</li>
      </ul>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">3. الطبقات الصوتية الأربع</span>
        <span class="k-ratio-chip">توزيع الأدوار</span>
      </div>
      <h4>الطبقات الأربع الأساسية لتوزيع واضح</h4>
      <ul class="k-physics-list">
        <li><strong>1. المقدمة الأمامية (اللحن الرئيسي / Lead):</strong> الصوت الغنائي أو الآلة المنفردة التي تروي القصة الرئيسية.</li>
        <li><strong>2. الأساس (الباص والإيقاع):</strong> يرسّخ الباص النغمة الأساسية الهارمونية بينما يثبّت الدرامز والإيقاع النبض.</li>
        <li><strong>3. البساط الهارموني (الباد والمرافقة):</strong> وتريات ممتدة، كورال، أورغن، أو تآلفات جيتار/بيانو إيقاعية في وسط الطيف.</li>
        <li><strong>4. اللحن المضاد والزخارف (Fills):</strong> ردود لحنية صغيرة تتدخل تحديداً حين يتنفس اللحن الرئيسي.</li>
      </ul>
      <div class="k-btn-row" style="margin-top:0.5rem;">
        <button type="button" class="btn-tool" data-play-custom="arr-sketch">▶ 1. مسودة بسيطة (لحن وباص)</button>
        <button type="button" class="btn-tool" data-play-custom="arr-full-layers">▶ 2. توزيع كامل بـ 4 طبقات</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">4. المناطق الصوتية وتوزيع التآلفات (Voicing)</span>
        <span class="k-ratio-chip">الوضوح مقابل التكدس</span>
      </div>
      <h4>لماذا تبدو بعض التوزيعات صافية وأخرى موحلة؟</h4>
      <ul class="k-physics-list">
        <li><strong>قانون التوافقيات (واسع في الأسفل، متقارب في الأعلى):</strong> أسفل <code>C3</code> تُربك الثالثات الضيقة المنطقة الجهيرة وتُغيمها (<em>حد المسافات المنخفضة / Low-Interval Limit</em>). خصّص الجهير للأساسات والخامسات والأوكتافات، وضع الثالثات والسابعات والامتدادات في الوسط والأعلى.</li>
        <li><strong>الوضع المغلق مقابل الوضع المفتوح (Drop-2):</strong> خفض ثاني أعلى نغمة في تآلف متقارب بمقدار أوكتاف يفتح المساحة الصوتية فوراً.</li>
        <li><strong>التكامل الإيقاعي:</strong> لتفادي التغطية الصوتية، اقرن النغمات الممتدة (الباد) بزخارف قصيرة وواضحة.</li>
      </ul>
      <div class="k-btn-row" style="margin-top:0.5rem;">
        <button type="button" class="btn-tool" data-play-custom="arr-voicing-muddy">▶ غائم: ثالثات ضيقة في الباص</button>
        <button type="button" class="btn-tool" data-play-custom="arr-voicing-open">▶ صافٍ: توزيع مفتوح متوازن</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">5. الديناميكية والحوار</span>
        <span class="k-ratio-chip">نداء واستجابة • دروب</span>
      </div>
      <h4>الحفاظ على التشويق من البداية حتى النهاية</h4>
      <ul class="article-steps-list">
        <li><strong>النداء والاستجابة (Call &amp; Response):</strong> تجيب المرافقة في فراغات الصوت الرئيسي.</li>
        <li><strong>الحركة العكسية واللحن المضاد:</strong> خط لحني ثانٍ يهبط بينما يصعد اللحن الرئيسي، أو يتحرك أثناء استقرار نغمة ممتدة.</li>
        <li><strong>قوة الحذف («الدروب / Drop»):</strong> سحب معظم الآلات فجأة لمازورة واحدة يخلق غالباً أثراً أعظم من إضافة آلات جديدة.</li>
      </ul>
      <div class="k-btn-row" style="margin-top:0.5rem;">
        <button type="button" class="btn-tool" data-play-custom="arr-call-response">▶ نداء واستجابة (سؤال / جواب)</button>
        <button type="button" class="btn-tool" data-play-custom="arr-counterpoint">▶ كونترابنط بحركة عكسية</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">6. إعادة التآلف وقائمة المراجعة</span>
        <span class="k-ratio-chip">النغمات نفسها، لون آخر</span>
      </div>
      <h4>تغيير الشعور بالكامل دون المساس بنغمة واحدة من اللحن</h4>
      <p>
        تُبقي <strong>إعادة التآلف (Reharmonization)</strong> اللحن كما هو تماماً مع تبديل التآلفات أسفله (مثل استبدال <code>C – G – C</code> البسيطة بـ <code>Fmaj7 – Fm6 – Am9</code>).
      </p>
      <div class="k-btn-row" style="margin-top:0.45rem;margin-bottom:0.65rem;">
        <button type="button" class="btn-tool" data-play-custom="arr-reharm-plain">▶ اللحن فوق تآلفات بسيطة (I–V–I)</button>
        <button type="button" class="btn-tool" data-play-custom="arr-reharm-cinema">▶ اللحن نفسه بإعادة تآلف سينمائية</button>
      </div>
      <div class="k-meta-box">
        <div><strong>5 أسئلة جوهرية لمراجعة توزيعاتك:</strong></div>
        <div>1. <strong>من يتحدث الآن؟</strong> يجب أن يتصدر عنصر رئيسي واحد فقط المشهد في كل لحظة.</div>
        <div>2. <strong>أين فراغات التنفس؟</strong> ضع الردود اللحنية في لحظات توقف الغناء.</div>
        <div>3. <strong>هل المنطقة الجهيرة نظيفة؟</strong> لا ثالثات ضيقة أسفل <code>C3</code>.</div>
        <div>4. <strong>هل يختلف المقطع عن اللازمة بوضوح؟</strong> نوّع في اتساع الأوكتافات والكثافة.</div>
        <div>5. <strong>اختبار زر الكتم (Mute):</strong> إن كتمت مساراً ولم تفقد الأغنية شيئاً، فامنحه دوراً حقيقياً أو احذفه!</div>
      </div>
      <div class="k-btn-row" style="margin-top:0.55rem;">
        <button type="button" class="btn-tool" data-jump-ref="ensembles">إلى الأوركسترا والمجموعات →</button>
        <button type="button" class="btn-tool" data-jump-ref="cadences">إلى القفلات والهارموني →</button>
        <button type="button" class="btn-tool" data-jump-ref="physics">إلى الفيزياء والتوافقيات →</button>
      </div>
    </article>
  `;
}

